294: bool IntersectRayAreaLight(float3 origin, float3 dir, AreaLight light, out float tHit, out float3 normalAtHit)
295: {
296:     float3 lpos    = float3(light.posX,     light.posY,     light.posZ);
297:     float3 ltan    = float3(light.tangentX, light.tangentY, light.tangentZ);
298:     float3 lnorm   = float3(light.normalX,  light.normalY,  light.normalZ);
299:     float3 lbitan  = cross(ltan, lnorm);
300: 
301:     // Single-sided: ray must approach from the front hemisphere
302:     // (i.e. dot(lnorm, -dir) > 0  =>  dot(lnorm, dir) < 0).
303:     float denom = dot(lnorm, dir);
304:     if (denom >= -1e-6) { tHit = -1.0; normalAtHit = float3(0, 0, 0); return false; }
305: 
306:     // Plane intersection: t = dot(lpos - origin, lnorm) / dot(lnorm, dir).
307:     float t = dot(lpos - origin, lnorm) / denom;
308:     if (t <= 0.001) { tHit = -1.0; normalAtHit = float3(0, 0, 0); return false; }
309: 
310:     // Bounds check in the rectangle's tangent / bitangent frame.
311:     float3 p = origin + t * dir;
312:     float3 d = p - lpos;
313:     float  u = dot(d, ltan);
314:     float  v = dot(d, lbitan);
315:     if (abs(u) > light.halfWidth || abs(v) > light.halfHeight)
316:     {
317:         tHit = -1.0; normalAtHit = float3(0, 0, 0); return false;
318:     }
319: 
320:     tHit        = t;
321:     normalAtHit = lnorm;
322:     return true;
323: }
