325: bool IntersectRaySphereLight(float3 origin, float3 dir, SphereLight light, out float tHit, out float3 normalAtHit)
326: {
327:     float3 c  = float3(light.posX, light.posY, light.posZ);
328:     float3 oc = origin - c;
329:     float  b  = dot(oc, dir);                              // half-b form
330:     float  cc = dot(oc, oc) - light.radius * light.radius;
331:     float  disc = b * b - cc;
332:     if (disc < 0.0) { tHit = -1.0; normalAtHit = float3(0, 0, 0); return false; }
333: 
334:     float s = sqrt(disc);
335:     float t = -b - s;              // entry point (front face for external rays)
336:     if (t <= 0.001) t = -b + s;    // origin inside the sphere -> exit point
337:     if (t <= 0.001) { tHit = -1.0; normalAtHit = float3(0, 0, 0); return false; }
338: 
339:     float3 p = origin + t * dir;
340:     tHit        = t;
341:     normalAtHit = normalize(p - c);
342:     return true;
343: }
